// Google Trends retorna JSON prefixado com )]}' (anti-XSSI)
const raw = String($input.item.json.data || $input.item.json);
const cleaned = raw.replace(/^\)\]\}',?/, '').trim();
let data;
try { data = JSON.parse(cleaned); }
catch(e) { return []; }

const days = data?.default?.trendingSearchesDays || [];
const termos = [];
days.forEach(day => {
  (day.trendingSearches || []).forEach(t => {
    const titulo = t?.title?.query;
    const traffic = t?.formattedTraffic;
    if (titulo) {
      termos.push({
        json: {
          fonte: 'google-trends',
          termo: titulo.toLowerCase(),
          volume_estimado: traffic || 'N/A',
          coletado_em: new Date().toISOString()
        }
      });
    }
  });
});
return termos;

// ML Trends retorna array simples
const items = $input.item.json || [];
return (Array.isArray(items) ? items : []).slice(0, 30).map(t => ({
  json: {
    fonte: 'ml-trends',
    termo: (t.keyword || '').toLowerCase(),
    volume_estimado: 'N/A',
    coletado_em: new Date().toISOString()
  }
})).filter(x => x.json.termo);
